  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px 20px;
  margin: 0 0 16px;
}

.placeholder {
  color: var(--muted);
  font-style: italic;
}

.privacy-note {
  color: var(--muted);
  font-size: 0.9rem;
  margin: 0;
}

