button {
  font: inherit;
  border-radius: 6px;
  padding: 10px 18px;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
}

button.primary {
  background: var(--accent);
  border-color: var(--accent);
