const hex = h => [1,3,5].map(i => parseInt(h.slice(i,i+2),16));
const over = (fg, a, bg) => fg.map((c,i) => c*a + bg[i]*(1-a));
const lum = c => { const [r,g,b] = c.map(v => { v/=255; return v <= 0.03928 ? v/12.92 : ((v+0.055)/1.055)**2.4 }); return 0.2126*r+0.7152*g+0.0722*b };
const cr = (a,b) => { const [x,y] = [lum(a),lum(b)].sort((p,q)=>q-p); return +((x+0.05)/(y+0.05)).toFixed(2) };
const glass = [22,27,37], A = 0.72;
const out = {};
for (const [name, behind] of [['gradient brightest #23203d', hex('#23203d')], ['gradient #1e2a44', hex('#1e2a44')], ['worst case white', [255,255,255]]]) {
  const g = over(glass, A, behind);
  const panel = over([255,255,255], 0.04, g);
  const chip = over(hex('#8fb4ff'), 0.14, g);
  out[name] = { text_on_glass: cr(hex('#e9ecf2'), g), muted_on_glass: cr(hex('#a3acbc'), g), muted_on_panel: cr(hex('#a3acbc'), panel), accent_chip: cr(hex('#8fb4ff'), chip) };
}
out.primary_button = cr(hex('#0d1320'), hex('#8fb4ff'));
out.footer_muted_on_bg = cr(hex('#a3acbc'), hex('#1e2a44'));
out

