  border: 1.5px solid var(--border);
}

.dot-done {
  background: var(--accent);
  border-color: var(--accent);
}

.dot-skipped {
  border-style: dashed;
  border-color: var(--muted);
}

.dot-current {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

