  width: 90px;
  height: 6px;
  border-radius: var(--radius-pill);
  background: var(--surface-hover);
  overflow: hidden;
}

.timer-bar span {
  display: block;
  height: 100%;
  border-radius: var(--radius-pill);
  background: var(--accent);
  transition: width 250ms linear;
}

.timer-near .timer-text {
  color: var(--warn);
}

.timer-near .timer-bar span {
  background: var(--warn);
}

.timer-over .timer-text {
  color: var(--over);
  font-weight: 600;
}

.timer-over .timer-bar span {
  background: var(--over);
}

/* Interview room: question and captions */

.question-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px 18px;
}

.question-card .label {
  margin-top: 0;
}

.question-card .question {
  margin: 0;
}

.captions {
  display: grid;
  gap: 4px;
}

.captions h3 {
  font-size: 0.8rem;
}

/* Phone screen orb */

.orb-wrap {
  display: grid;
  justify-items: center;
  gap: 18px;
  width: 100%;
}

.orb {
  --level: 0;
  position: relative;
  width: min(55%, 220px);
  aspect-ratio: 1;
}

.orb-glow,
.orb-core {
  position: absolute;
  border-radius: 50%;
  transition: opacity 300ms ease;
}

.orb-glow {
  inset: -28%;
  background: radial-gradient(circle, var(--accent-glow) 0%, transparent 62%);
  opacity: calc(0.35 + var(--level) * 0.65);
  transform: scale(calc(0.92 + var(--level) * 0.28));
}

.orb-core {
  inset: 0;
  background: radial-gradient(circle at 35% 30%, #dbe7ff 0%, var(--accent) 42%, var(--accent-deep) 100%);
  transform: scale(calc(0.95 + var(--level) * 0.1));
}

.orb-speaking .orb-glow {
  opacity: calc(0.55 + var(--level) * 0.45);
}

.orb-thinking .orb-core,
.orb-thinking .orb-glow {
  animation: orb-breathe 2.4s ease-in-out infinite;
}

.orb-loading,
.orb-paused {
  opacity: 0.45;
}

@keyframes orb-breathe {
  50% {
    transform: scale(1.05);
    opacity: 0.85;
  }
}

.orb-label {
  color: var(--muted);
  margin: 0;
}""",1)
open(p,'w').write(s)
EOF
